mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decideWhatsApp } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g5-2/bot.mjs';

const ts = '1767272400'; // 2026-01-01T13:00:00Z
const at = (ms) => new Date(Date.parse('2026-01-01T13:00:00Z') + ms);
const H = 3600e3;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: ts, ...over });

const cases = [
  ['text, opted in, 1 min after inbound', { type: 'text', contact: c() }, at(60e3), { allowed: true, reason: null }],
  ['text, 23h59m after inbound', { type: 'text', contact: c() }, at(24 * H - 60e3), { allowed: true, reason: null }],
  ['text, exactly 24h after inbound', { type: 'text', contact: c() }, at(24 * H), { allowed: false, reason: 'customer_service_window_closed' }],
  ['text, 3 days after inbound', { type: 'text', contact: c() }, at(72 * H), { allowed: false, reason: 'customer_service_window_closed' }],
  ['text, never wrote to us', { type: 'text', contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: false, reason: 'customer_service_window_closed' }],
  ['template, window closed', { type: 'template', contact: c() }, at(72 * H), { allowed: true, reason: null }],
  ['template, never wrote to us', { type: 'template', contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: true, reason: null }],
  ['text, not opted in, window open', { type: 'text', contact: c({ optedIn: false }) }, at(60e3), { allowed: false, reason: 'not_opted_in' }],
  ['template, not opted in', { type: 'template', contact: c({ optedIn: false }) }, at(60e3), { allowed: false, reason: 'not_opted_in' }],
  ['optedIn missing', { type: 'template', contact: { lastInboundTimestamp: null } }, at(0), { allowed: false, reason: 'not_opted_in' }],
  ['unknown type', { type: 'image', contact: c() }, at(60e3), { allowed: false, reason: 'unsupported_message_type' }],
  ['timestamp is a number, not string', { type: 'text', contact: c({ lastInboundTimestamp: 1767272400 }) }, at(60e3), { allowed: false, reason: 'invalid_inbound_timestamp' }],
  ['timestamp in milliseconds (wrong unit)', { type: 'text', contact: c({ lastInboundTimestamp: '1767272400000' }) }, at(60e3), { allowed: false, reason: 'invalid_inbound_timestamp' }],
  ['timestamp not numeric', { type: 'text', contact: c({ lastInboundTimestamp: 'abc' }) }, at(60e3), { allowed: false, reason: 'invalid_inbound_timestamp' }],
  ['timestamp in the future', { type: 'text', contact: c() }, at(-60e3), { allowed: false, reason: 'invalid_inbound_timestamp' }],
  ['invalid now', { type: 'text', contact: c() }, new Date('nope'), { allowed: false, reason: 'invalid_inbound_timestamp' }],
];

let failed = 0;
for (const [name, msg, now, want] of cases) {
  try {
    assert.deepEqual(decideWhatsApp(msg, now), want);
    console.log('ok  ', name);
  } catch (e) {
    failed++;
    console.log('FAIL', name, JSON.stringify(decideWhatsApp(msg, now)));
  }
}
console.log(failed ? `${failed} failed` : `all ${cases.length} passed`);
process.exit(failed ? 1 : 0);
EOF
node --version && node /tmp/bot-check/check.mjs
